mapper.select:
SELECT COUNT(1)
FROM whale_roles
WHERE name = #{name}

mapper.update:
UPDATE whale_roles
SET is_deleted = 1,
    updated_at = NOW(6),
    updated_by = #{deletedBy},
    deleted_at = NOW(6),
    deleted_by = #{deletedBy}
WHERE id = #{roleId}
  AND tenant_id = #{tenantId}
  AND is_static = 0
  AND is_deleted = 0
